nativeLooks.lookAvailable:
function uo(e, t, n, r) {
  switch (n) {
    case `shiny`:
      return so(e, t, r);
    case `spectral`:
      return lo(e, t);
    case `classic`:
      return si(e, t, r);
    case `m1`:
      return oi(e, t, 1);
    case `m2`:
      return oi(e, t, 2);
    case `t1`:
    case `t2`:
      return ai(e, t, n);
  }
}

nativeLooks.decodeSkin:
function Er(e) {
  return !Number.isInteger(e) || e === 0
    ? null
    : e < 0
      ? e > -1e3
        ? { member: -e, look: `spectral` }
        : null
      : e < 1e3
        ? { member: e, look: `shiny` }
        : e < A[0]
          ? { member: e - wr, look: `classic` }
          : e < A[1]
            ? { member: e - A[0], look: `m1` }
            : e < A[1] + 1e3
              ? { member: e - A[1], look: `m2` }
              : e < j[0] + 1e3
                ? { member: e - j[0], look: `t1` }
                : e < j[1] + 1e3
                  ? { member: e - j[1], look: `t2` }
                  : null;
}

nativeLooks.normalizeTeam:
function fo(e, t) {
  return !Array.isArray(t) || t.length > 40
    ? null
    : [
        ...new Set(
          t.filter((t) => Number.isInteger(t) && e.league.includes(t)),
        ),
      ].slice(0, 6);
}
